const { writeSync } = require('node:fs');
// This diagnostic may expose an engine crash. Disable only this child's core
// dumping, including piped crash reporters that can ignore RLIMIT_CORE.
const ffi = require('../../node_modules/koffi');
const prctl = ffi.load('libc.so.6').func('int prctl(int option, unsigned long a, unsigned long b, unsigned long c, unsigned long d)');
if (prctl(4, 0, 0, 0, 0) !== 0 || prctl(3, 0, 0, 0, 0) !== 0) throw new Error('Cannot disable diagnostic child core dumps');
const method = process.env.LASM_PROBE_STACK_METHOD;
Error.prepareStackTrace = (_, frames) => {
  writeSync(2, 'formatter entered\n');
  if (method === 'count') return JSON.stringify({ count: frames.length });
  return JSON.stringify(frames.map(frame => {
    try { return typeof frame[method] === 'function' ? frame[method]() : 'unavailable'; }
    catch (error) { return { error: error.message }; }
  }));
};

