const { writeSync } = require('node:fs');
const ffi = require('../../node_modules/koffi');
const prctl = ffi.load('libc.so.6').func('int prctl(int option, unsigned long a, unsigned long b, unsigned long c, unsigned long d)');
if (prctl(4,0,0,0,0) || prctl(3,0,0,0,0)) throw new Error('core suppression failed');
const describe = key => {
 const descriptor=Object.getOwnPropertyDescriptor(Error,key);
 return descriptor ? Object.fromEntries(Object.entries(descriptor).map(([k,v])=>[k,typeof v==='function'?'function':v])) : null;
};
writeSync(2,JSON.stringify({thread:require('node:worker_threads').isMainThread,prepare:describe('prepareStackTrace'),limit:describe('stackTraceLimit')})+'\n');
const format = (_,frames)=>frames.map(f=>'    at '+f.toString()).join('\n');
if(process.env.LASM_STACK_PROPERTY_MODE==='define'){
 Object.defineProperty(Error,'stackTraceLimit',{value:100,configurable:true,writable:true});
 Object.defineProperty(Error,'prepareStackTrace',{value:format,configurable:true,writable:true});
}else{
 Error.stackTraceLimit=100; Error.prepareStackTrace=format;
}
require('../backtrace-names-r1/stripped.cjs');

