const fs = require('node:fs');
const assert = require('node:assert/strict');
const path = require('node:path');
const source = fs.readFileSync(path.join(__dirname, '../../scripts/full-lean/host-library.js'), 'utf8');
let library;
new Function('addToLibrary', 'stringToNewUTF8', source.slice(0, source.indexOf('  lasm_collect_loaded_libraries__deps:')) + '});')(value => { library = value; }, text => text);
module.exports = function capture() {
 const before = ['stackTraceLimit','prepareStackTrace'].map(key => Object.getOwnPropertyDescriptor(Error,key));
 const stack = library.lasm_host_backtrace();
 const after = ['stackTraceLimit','prepareStackTrace'].map(key => Object.getOwnPropertyDescriptor(Error,key));
 assert.deepEqual(after,before,'capture restores descriptors and values');
 assert.match(stack,/wasm-function\[\d+\]/);
 assert.doesNotMatch(stack,/at unknown/);
 return stack;
};

